function sumsWithReuse(parts: number[], target: number): number[][] {
  const out: number[][] = [];
  const cur: number[] = [];
  const go = (i: number, left: number): void => {
    if (left === 0) { out.push([...cur]); return; }
    if (i === parts.length || left < 0) return;
    cur.push(parts[i]);
    go(i, left - parts[i]); // take it again later if it still fits
    cur.pop();
    go(i + 1, left);        // done with this part
  };
  go(0, target);
  return out;
}

