function sumsWithReuse(parts: number[], target: number): number[][] {
  const a = [...parts].sort((x, y) => x - y);
  const out: number[][] = [];
  const cur: number[] = [];
  const go = (start: number, left: number): void => {
    if (left === 0) { out.push([...cur]); return; }
    for (let i = start; i < a.length; i++) {
      if (a[i] > left) break; // sorted: every later part is too big as well
      cur.push(a[i]);
      go(i, left - a[i]);     // i, not i + 1: the same part may come again
      cur.pop();
    }
  };
  go(0, target);
  return out;
}

